p-bottom{display:flex;justify-content:space-between;align-items:center;gap:8px}.price{font-size:15px;font-weight:650;white-space:nowrap;letter-spacing:-.03em}.price small{font-size:10px;color:var(--muted);font-weight:400}.add{border:1px solid var(--line);width:35px;height:35px;display:grid;place-items:center;transition:.2s}.add:hover{color:white;background:var(--accent);border-color:var(--accent)}.stock{font-size:10px;color:var(--muted);margin-top:7px;display:flex;align-items:center;gap:5px}.stock:before{content:'';display:block;height:5px;width:5px;background:#818d70;border-radius:50%}.stock.no:before{background:#a79c8b}.empty{padding:70px 15px;text-align:center;border:1px solid var(--line);color:var(--muted);grid-column:1/-1}.empty h3{font-size:24px;color:var(--ink);margin-bottom:8px}.empty button{margin-top:18px}.backdrop{position:fixed;inset:0;background:#0006;z-index:40;display:none}.backdrop.show{display:block}.dialog{position:fixed;inset:50% auto auto 50%;transform:translate(-50%,-50%);max-width:min(680px,calc(100% - 30px));width:100%;background:var(--bg);z-index:50;padding:26px;display:none;max-height:90vh;overflow:auto}.dialog.show{display:block}.dialog-header{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:20px}.dialog-header h2{font-size:26px}.dialog .sample{aspect-ratio:1.3;max-width:320px}.dialog-product{display:grid;grid-template-columns:1fr 1fr;gap:22px}.dialog-product p{margin:10px 0;line-height:1.6}.dialog-product .btn{margin-top:10px}.search-field{display:flex;gap:8px}.search-field input{border:1px solid var(--line);background:var(--paper);color:var(--ink);min-height:48px;padding:0 12px;flex:1;min-width:0}.toast{position:fixed;bottom:20px;left:50%;transform:translateX(-50%);background:var(--dark);color:white;z-index:60;padding:14px 20px;font-size:12px;display:none;box-shadow:0 5px 25px #0002}.toast.show{display:block}.mobile-nav{display:none}.only-mobile{display:none}
@media(max-width:1050px){.nav{gap:20px}.hero{min-height:550px}.hero-media{min-height:500px}.products{grid-template-columns:repeat(2,minmax(0,1fr))}.catalog-grid{grid-template-columns:225px minmax(0,1fr);gap:24px}.material-layout{gap:35px}.section{padding-block:75px}}
@media(max-width:760px){:root{--gutter:20px}.topbar .wrap{font-size:9px}.topbar .wrap>span{max-width:120px}.header-inner{height:64px;gap:8px}.wordmark{font-size:19px}.nav{display:none}.tools{gap:0}.
